export async function pollConversations(env,{now=new Date(),limit=25,fetchThread=productionFetchThread,onActivity=defaultActivity}={}){const clock=new Date(now),cutoff=new Date(clock.getTime()-60*60000).toISOString();const {results:messages=[]}=await env.DB.prepare(`SELECT m.* FROM gmail_messages m LEFT JOIN conversation_state s ON s.message_id=m.id WHERE ${roots} AND (s.last_sync_attempt_at IS NULL OR s.last_sync_attempt_at<=?) ORDER BY COALESCE(s.last_sync_attempt_at,''),m.sent_at,m.id LIMIT ?`).bind(cutoff,Math.max(1,Math.min(100,Number(limit)||25))).all();const result={considered:messages.length,polled:0,failed:0};for(const m of messages){try{await syncConversation(env,{workspaceId:m.workspace_id,userId:m.sent_by},m.id,{now:clock,fetchThread,onActivity});result.polled++;}catch{result.failed++;try{const operation=await conversationOperation(env,{workspaceId:m.workspace_id,userId:m.sent_by},m);await recoverCrm(operation.env,m,{onActivity,now:clock});}catch{}}}return result;}

async function productionSend({env,connection,conversation,step,inReplyTo,guard,now}){let token,mime;try{token=await accessToken(env,connection);mime=buildMimeMessage({from:connection.google_email,to:conversation.recipient,subject:step.subject,body:step.body});if(inReplyTo&&!/[\r\n]/.test(inReplyTo))mime=`In-Reply-To: ${inReplyTo}\r\nReferences: ${inReplyTo}\r\n${mime}`;}catch(cause){throw Object.assign(cause,{deliveryNotAttempted:true});}try{if(!inReplyTo||/[\r\n]/.test(inReplyTo))throw Error('Original Gmail Message-ID is missing');await syncConversation(env,{workspaceId:conversation.workspace_id},conversation.id,{now,fetchThread:()=>fetchGmailThread(token,conversation.gmail_thread_id)});await guard();}catch(cause){throw Object.assign(cause,{deliveryNotAttempted:true});}return sendGmailMessage(token,mime,fetch,conversation.gmail_thread_id);}
async function planFailure(env,p,error,status='needs_review'){await env.DB.batch([env.DB.prepare('UPDATE conversation_plans SET status=?,error=? WHERE id=? AND status=\'active\'').bind(status,error,p.id),env.DB.prepare("UPDATE conversation_plan_steps SET status='held',error=? WHERE plan_id=? AND status IN ('queued','sending')").bind(error,p.id),env.DB.prepare("UPDATE conversation_state SET revision=revision+1,status='needs_review',reason=?,next_action='Review the held follow-up plan; no automatic retry is scheduled',task_status='pending' WHERE message_id=?").bind(error,p.message_id)]);}
// Restore only facts already proven by a durable, hash-matched acceptance
// receipt. This path never calls a provider or reactivates remaining follow-ups.
