export async function handleConversationRoute(request,env,cors={},options={}){const url=new URL(request.url);if(url.pathname!=='/api/conversation-workflows'&&!url.pathname.startsWith('/api/conversation-workflows/')&&url.pathname!=='/api/conversations'&&!url.pathname.startsWith('/api/conversations/'))return null;try{const token=cookieValue(request,'leadintel_session');if(!token)return json({error:'Authentication required'},401,cors);const user=await env.DB.prepare("SELECT u.id FROM users u JOIN sessions s ON s.user_id=u.id WHERE s.token_hash=? AND s.expires_at>datetime('now')").bind(await sha256(token)).first();if(!user)return json({error:'Authentication required'},401,cors);const workspaceId=url.searchParams.get('workspace_id');if(!workspaceId)return json({error:'Workspace is required'},400,cors);const member=await env.DB.prepare('SELECT role FROM workspace_members WHERE workspace_id=? AND user_id=?').bind(workspaceId,user.id).first();if(!member||!['owner','sales','researcher'].includes(member.role))return json({error:'Workspace access denied'},403,cors);const scope={workspaceId,userId:user.id,role:member.role};scope.guard=await contactRequestGuard(request,env,scope);scope.writeAuthority=scope.guard.writeAuthority;if(url.pathname.startsWith('/api/conversation-workflows')){if(request.method==='GET'&&url.pathname==='/api/conversation-workflows')return json(await listConversationWorkflows(env,scope),200,cors);if(request.method!=='POST')return json({error:'Route not found'},404,cors);const match=url.pathname.match(/^\/api\/conversation-workflows\/([^/]+)\/(deactivate|delete)$/);if(match)return json(await disableConversationWorkflow(env,scope,decodeURIComponent(match[1]),match[2]==='delete'),200,cors);if(url.pathname!=='/api/conversation-workflows')return json({error:'Route not found'},404,cors);const text=await request.text();if(text.length>50000)fail('Request is too large',413);return json(await saveConversationWorkflow(env,scope,JSON.parse(text),options),200,cors);}if(request.method==='GET'&&url.pathname==='/api/conversations')return json(await listConversations(env,scope,options),200,cors);const match=url.pathname.match(/^\/api\/conversations\/([^/]+)\/(sync|plan|cancel|task|workflow|takeover|resume)$/);if(request.method!=='POST'||!match)return json({error:'Conversation route not found'},404,cors);if(!['owner','sales'].includes(scope.role))return json({error:'Workspace role is not permitted'},403,cors);const id=decodeURIComponent(match[1]),action=match[2];let conversation;if(action==='sync')conversation=await syncConversation(env,scope,id,options);else if(action==='cancel')conversation=await cancelConversationPlan(env,scope,id);else {const text=await request.text();if(text.length>50000)return json({error:'Request is too large'},413,cors);let input;try{input=JSON.parse(text);}catch{fail('Valid JSON is required',400);}if(action==='workflow')conversation=await applyConversationWorkflow(env,scope,id,input,options);else if(action==='takeover')conversation=await takeoverConversationWorkflow(env,scope,id,input);else if(action==='resume')conversation=await resumeConversationWorkflow(env,scope,id,input,options);else if(action==='plan')conversation=await approveConversationPlan(env,scope,id,input,options);else {if(input.status!=='done')fail('Task status must be done',400);conversation=await completeConversationTask(env,scope,id,input);}}return json({conversation},200,cors);}catch(cause){return json({error:String(cause?.message||'Conversation operation failed').slice(0,500)},cause.status||502,cors);}}

export async function validateWorkflowResumeContext(env,scope,id,now){const m=await root(env,scope,id),p=await env.DB.prepare('SELECT * FROM conversation_plans WHERE message_id=? AND workspace_id=?').bind(id,scope.workspaceId).first();if(!p)fail('Approved plan is unavailable; review is required');const authority=await planAuthority(env,p);const connection=await connectionFor(env,scope.workspaceId),identity=await identities(env,m),policy=await effectivePolicy(env,scope.workspaceId),member=await env.DB.prepare('SELECT role FROM workspace_members WHERE workspace_id=? AND user_id=?').bind(scope.workspaceId,p.approved_by).first();if(JSON.stringify(identitySnapshot(identity))!==JSON.stringify(authority.original.identity))fail('Original reviewed recipient identity changed; review is required');if(member?.role!=='owner'||mailboxIdentity(connection)!==p.mailbox_identity||identity.company?.id!==p.company_id||identity.contact?.id!==p.contact_id||String(identity.company?.updated_at||'')!==p.company_revision||String(identity.contact?.updated_at||'')!==p.contact_revision||['suppressed','archived'].includes(identity.company?.lifecycle_status)||!await confirmedContact(env,m,identity.contact,now)||await isContactSuppressed(env.DB,scope.workspaceId,m.recipient)||policy.paused||policy.emergencyStop||await sha256(JSON.stringify(policy))!==p.policy_revision)fail('Approved owner, mailbox, CRM, suppression or policy context changed; review is required');}

export async function getConversation(env,scope,id){return expose(env,await root(env,scope,id));}
export async function workflowMutationAssertion(env,scope,id,expectedContext){const m=await root(env,scope,id),state=await env.DB.prepare('SELECT * FROM conversation_state WHERE message_id=? AND workspace_id=?').bind(id,scope.workspaceId).first(),identity=await identities(env,m),connection=await connectionFor(env,scope.workspaceId);if(await contextVersion(env,m,state,identity,connection)!==expectedContext)fail('Conversation context changed before workflow activation');const assignment=await env.DB.prepare("SELECT json_array(workflow_id,revision,status,first_step_index,assigned_at) snapshot FROM conversation_workflow_assignments WHERE message_id=? AND workspace_id=?").bind(id,scope.workspaceId).first();const guardId=uuid();return {insert:env.DB.prepare('INSERT INTO conversation_workflow_mutation_guards VALUES(?,?,?,?,?)').bind(guardId,id,scope.workspaceId,state.revision,assignment?.snapshot||'null'),remove:env.DB.prepare('DELETE FROM conversation_workflow_mutation_guards WHERE id=?').bind(guardId)};}
